changeSet.sql:
CREATE SEQUENCE im_room_id START WITH 1 INCREMENT BY 1;
CREATE TABLE im_room ( id BIGINT NOT NULL, id_sector BIGINT NOT NULL, name VARCHAR(255) NOT NULL, normalized_name VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT pk_room PRIMARY KEY (id), CONSTRAINT fk_room_sector FOREIGN KEY (id_sector) REFERENCES im_sector (id), CONSTRAINT uk_room_sector_name UNIQUE (id_sector, normalized_name) );
ALTER TABLE im_item ADD COLUMN id_room BIGINT; ALTER TABLE im_item ADD COLUMN id_found_room BIGINT; ALTER TABLE im_item ADD CONSTRAINT fk_item_room FOREIGN KEY (id_room) REFERENCES im_room (id); ALTER TABLE im_item ADD CONSTRAINT fk_item_found_room FOREIGN KEY (id_found_room) REFERENCES im_room (id);
ALTER TABLE im_item_audit ADD COLUMN id_found_room BIGINT; ALTER TABLE im_item_audit ADD COLUMN id_expected_room BIGINT; ALTER TABLE im_item_audit ADD COLUMN divergent BOOLEAN NOT NULL DEFAULT false; ALTER TABLE im_item_audit ADD CONSTRAINT fk_audit_found_room FOREIGN KEY (id_found_room) REFERENCES im_room (id); ALTER TABLE im_item_audit ADD CONSTRAINT fk_audit_expected_room FOREIGN KEY (id_expected_room) REFERENCES im_room (id);
INSERT INTO im_room (id, id_sector, name, normalized_name) SELECT nextval('im_room_id'), ranked.id_sector, ranked.display, ranked.norm FROM ( SELECT counted.id_sector, counted.display, counted.norm, row_number() OVER (PARTITION BY counted.id_sector, counted.norm ORDER BY counted.total DESC, counted.display) AS position FROM ( SELECT inv.id_sector, btrim(regexp_replace(it.locale, '\s+', ' ', 'g')) AS display, translate(lower(btrim(regexp_replace(it.locale, '\s+', ' ', 'g'))), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') AS norm, count(*) AS total FROM im_item it JOIN im_inventory inv ON inv.id = it.id_inventory WHERE inv.id_sector IS NOT NULL AND it.locale IS NOT NULL AND btrim(it.locale) != '' GROUP BY inv.id_sector, btrim(regexp_replace(it.locale, '\s+', ' ', 'g')), translate(lower(btrim(regexp_replace(it.locale, '\s+', ' ', 'g'))), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ) counted ) ranked WHERE ranked.position = 1;
UPDATE im_item it SET id_room = room.id FROM im_inventory inv, im_room room WHERE inv.id = it.id_inventory AND room.id_sector = inv.id_sector AND it.locale IS NOT NULL AND btrim(it.locale) != '' AND room.normalized_name = translate(lower(btrim(regexp_replace(it.locale, '\s+', ' ', 'g'))), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc');
